SQL_STMT_U.val:
SELECT x.customer_id, x.SlipDate, x.SalesSlipNo, x.ProductName, x.SalesAmount, x.TaxAmount, x.TaxMark, x.receipt_amount, CASE WHEN @prev_customer IS NULL OR @prev_customer <> x.customer_id THEN @balance := ( SELECT COALESCE(( SELECT rf.previous_balance FROM receivables_file AS rf JOIN ( SELECT customer_id, MAX(`year_month`) AS ym FROM receivables_file WHERE customer_id = x.customer_id AND `year_month` <= ':3' GROUP BY customer_id ) AS latest ON latest.customer_id = rf.customer_id AND latest.ym = rf.`year_month` LIMIT 1 ), 0) ) WHEN x.ProductName = '【 繰 越 残 高 】' THEN @balance ELSE @balance := @balance + COALESCE(x.SalesAmount, 0) + COALESCE(x.TaxAmount, 0) - COALESCE(x.receipt_amount, 0) END AS RunningBalance,
CASE WHEN @prev_customer IS NULL OR @prev_customer <> x.customer_id THEN @group_no := @group_no + 1 ELSE @group_no END AS GroupNo,
@prev_customer := x.customer_id AS _update_prev
FROM ( /* --- 繰越残高（条件付き出力） --- */ SELECT c.id AS customer_id, DATE_SUB(':2', INTERVAL 1 DAY) AS SlipDate, NULL AS SalesSlipNo, '【 繰 越 残 高 】' AS ProductName, 0 AS SalesAmount, 0 AS TaxAmount, '' AS TaxMark, 0 AS receipt_amount, 0 AS LineNo FROM customer AS c WHERE ( (:1 = 0 OR c.id = :1) AND ( EXISTS ( SELECT 1 FROM receivables_file AS rf WHERE rf.customer_id = c.id AND COALESCE(rf.previous_balance,0) <> 0 ) OR EXISTS ( SELECT 1 FROM sale s WHERE s.customer_id = c.id AND s.sales_date BETWEEN ':2' AND ':3' ) OR EXISTS ( SELECT 1 FROM receipt r WHERE r.billing_customer_id = c.id AND r.receipt_date BETWEEN ':2' AND ':3' ) ) )
UNION ALL
/* --- 売上 --- */ SELECT s.customer_id, s.sales_date AS SlipDate, s.id AS SalesSlipNo, ( SELECT sd2.transaction_specific_product_name FROM sale_detail AS sd2 WHERE sd2.sale_id = s.id ORDER BY sd2.id LIMIT 1 ) AS ProductName, ( COALESCE(s.standard_sales_amount, 0) + COALESCE(s.standard_return_amount, 0) + COALESCE(s.standard_discount_amount, 0) + COALESCE(s.reduced_sales_amount, 0) + COALESCE(s.reduced_return_amount, 0) + COALESCE(s.reduced_discount_amount, 0) ) AS SalesAmount, (COALESCE(s.standard_tax, 0) + COALESCE(s.reduced_tax, 0)) AS TaxAmount, ( SELECT CASE WHEN p2.tax_rate_type = 2 THEN '＊' ELSE '' END FROM sale_detail sd2 LEFT JOIN product p2 ON p2.product_cd = sd2.product_cd WHERE sd2.sale_id = s.id ORDER BY sd2.id LIMIT 1 ) AS TaxMark, 0 AS receipt_amount, 1 AS LineNo FROM sale AS s WHERE (:1 = 0 OR s.customer_id = :1) AND s.sales_date BETWEEN ':2' AND ':3'
UNION ALL
/* --- 入金 --- */ SELECT r.billing_customer_id AS customer_id, r.receipt_date AS SlipDate, r.id AS SalesSlipNo, '【 入 金 】' AS ProductName, 0 AS SalesAmount, 0 AS TaxAmount, '' AS TaxMark, (COALESCE(r.amount, 0) + COALESCE(r.fee, 0)) AS receipt_amount, 99999 AS LineNo FROM receipt AS r WHERE (:1 = 0 OR r.billing_customer_id = :1) AND r.receipt_date BETWEEN ':2' AND ':3' ) AS x, (SELECT @balance := 0, @prev_customer := NULL, @group_no := 0) AS vars
ORDER BY x.customer_id, x.SlipDate, x.SalesSlipNo, x.LineNo;

SELECT x.customer_id, x.SlipDate, x.SalesSlipNo, x.ProductName, x.OriginType, x.SalesQuantity, x.SalesUnitName, x.UnitPrice, x.UnitPriceTotal, x.TaxMark, x.row_no, x.receipt_amount, CASE WHEN @prev_customer IS NULL OR @prev_customer <> x.customer_id THEN @balance := ( SELECT COALESCE(( SELECT rf.previous_balance FROM receivables_file AS rf JOIN ( SELECT customer_id, MAX(`year_month`) AS ym FROM receivables_file WHERE customer_id = x.customer_id AND `year_month` <= ':3' GROUP BY customer_id ) AS latest ON latest.customer_id = rf.customer_id AND latest.ym = rf.`year_month` LIMIT 1 ), 0) ) WHEN x.ProductName = '【 繰 越 残 高 】' THEN @balance ELSE @balance := @balance + COALESCE(x.UnitPriceTotal, 0) - COALESCE(x.receipt_amount, 0) END AS RunningBalance,
CASE WHEN @prev_customer IS NULL OR @prev_customer <> x.customer_id THEN @group_no := @group_no + 1 ELSE @group_no END AS GroupNo,
@prev_customer := x.customer_id AS _update_prev
FROM ( /* --- 繰越残高（条件付き出力） --- */ SELECT c.id AS customer_id, DATE_SUB(':2', INTERVAL 1 DAY) AS SlipDate, NULL AS SalesSlipNo, '【 繰 越 残 高 】' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, 0 AS UnitPriceTotal, '' AS TaxMark, NULL AS row_no, 0 AS receipt_amount, 0 AS LineNo FROM customer AS c WHERE ( (:1 = 0 OR c.id = :1) AND ( EXISTS ( SELECT 1 FROM receivables_file AS rf WHERE rf.customer_id = c.id AND COALESCE(rf.previous_balance,0) <> 0 ) OR EXISTS ( SELECT 1 FROM sale s WHERE s.customer_id = c.id AND s.sales_date BETWEEN ':2' AND ':3' ) OR EXISTS ( SELECT 1 FROM receipt r WHERE r.billing_customer_id = c.id AND r.receipt_date BETWEEN ':2' AND ':3' ) ) )
UNION ALL
/* --- 売上明細（sale_detail基点） --- */ SELECT s.customer_id, s.sales_date AS SlipDate, s.id AS SalesSlipNo, sd.transaction_specific_product_name AS ProductName, o.origin_name AS OriginType, sd.quantity AS SalesQuantity, u.name AS SalesUnitName, sd.unit_price AS UnitPrice, (sd.quantity * sd.unit_price) AS UnitPriceTotal, CASE WHEN pm.tax_rate_type = 2 THEN '＊' ELSE '' END AS TaxMark, sd.row_no AS row_no, 0 AS receipt_amount, sd.row_no AS LineNo FROM sale_detail AS sd INNER JOIN sale AS s ON s.id = sd.sale_id LEFT JOIN origin AS o ON o.id = sd.origin_id LEFT JOIN unit AS u ON u.id = sd.unit_id LEFT JOIN product AS pm ON pm.id = sd.product_cd WHERE (:1 = 0 OR s.customer_id = :1) AND s.sales_date BETWEEN ':2' AND ':3'
UNION ALL
/* --- 消費税レコード（伝票単位でSUMあり） --- */ SELECT s.customer_id, s.sales_date AS SlipDate, s.id AS SalesSlipNo, '【 消 費 税 】' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, (COALESCE(s.standard_tax,0) + COALESCE(s.reduced_tax,0)) AS UnitPriceTotal, '' AS TaxMark, 9999 AS row_no, 0 AS receipt_amount, 9999 AS LineNo FROM sale AS s WHERE (:1 = 0 OR s.customer_id = :1) AND s.sales_date BETWEEN ':2' AND ':3' AND (COALESCE(s.standard_tax,0) + COALESCE(s.reduced_tax,0)) <> 0
UNION ALL
/* --- 入金 --- */ SELECT r.billing_customer_id AS customer_id, r.receipt_date AS SlipDate, r.id AS SalesSlipNo, '【 入 金 】' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, 0 AS UnitPriceTotal, '' AS TaxMark, NULL AS row_no, (COALESCE(r.amount, 0) + COALESCE(r.fee, 0)) AS receipt_amount, 99999 AS LineNo FROM receipt AS r WHERE (:1 = 0 OR r.billing_customer_id = :1) AND r.receipt_date BETWEEN ':2' AND ':3' ) AS x, (SELECT @balance := 0, @prev_customer := NULL, @group_no := 0) AS vars
ORDER BY x.customer_id, x.SlipDate, x.SalesSlipNo, x.LineNo;
